require_once __DIR__ . '/../../includes/admin_auth.php';require_admin();$id=valid_id($_GET['id']??$_POST['id']??null);if($id===null)redirect('index.php');$get=$pdo->prepare('SELECT syllabus.id,syllabus.module_title,courses.title AS course_title FROM syllabus INNER JOIN courses ON courses.id=syllabus.course_id WHERE syllabus.id=:id LIMIT 1');$get->execute(['id'=>$id]);$module=$get->fetch();if(!$module)redirect('index.php');if(is_post_request()){if(!verify_csrf_token($_POST['csrf_token']??null))exit('Invalid request.');$delete=$pdo->prepare('DELETE FROM syllabus WHERE id=:id');$delete->execute(['id'=>$id]);redirect('index.php');}admin_header('Delete Syllabus Module','syllabus/index.php');?><div class="card table-card"><div class="card-body p-4"><h2 class="h5">Delete “<?=e($module['module_title'])?>”?</h2><p class="text-secondary">Course: <?=e($module['course_title'])?></p><form method="post"><input type="hidden" name="id" value="<?=e($id)?>"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><button class="btn btn-danger" type="submit">Confirm Delete</button><a class="btn btn-outline-secondary ms-2" href="index.php">Cancel</a></form></div></div><?php admin_footer();?>
